INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63921997', 63921997, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pemotretan Drone', 'Jasa Lainnya', 'E-Purchasing', 'Aceh, Pidie Jaya (Kab.)', 432000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '1 Paket', 'Pekerjaan Pemotretan Drone adalah kegiatan pengambilan data visual udara (foto dan/atau video) menggunakan wahana tanpa awak (drone) untuk memperoleh gambaran kondisi eksisting wilayah/objek tertentu. Kegiatan ini meliputi: Persiapan dan perencanaan jalur terbang (flight plan); Pengambilan foto udara dan/atau video udara sesuai kebutuhan; Pengolahan awal hasil pemotretan; Penyampaian hasil dalam bentuk softcopy dan/atau laporan singkat hasil kegiatan. Hasil pemotretan digunakan sebagai bahan dokumentasi, pemetaan, monitoring kegiatan, perencanaan, atau kebutuhan administrasi lainnya.', 'a. Peralatan Drone kamera resolusi minimal 12 MP (disarankan ≥ 20 MP); Kamera stabil dengan gimbal 3-axis; GPS positioning aktif; Kapasitas baterai memadai untuk cakupan lokasi. b. Pelaksanaan Ketinggian terbang disesuaikan dengan kebutuhan detail objek; Pemotretan dilakukan pada kondisi cuaca cerah/aman; Operator drone memiliki pengalaman dan mematuhi ketentuan keselamatan penerbangan drone. c. Output/Hasil Foto udara berwarna resolusi tinggi (format JPG/PNG); Video udara (jika diperlukan) minimal kualitas Full HD (1080p); Data diserahkan dalam media penyimpanan (flashdisk/drive/cloud); Dokumentasi dilengkapi keterangan lokasi dan waktu pengambilan. d. Ketentuan Lain Pekerjaan dilaksanakan sesuai jadwal yang disepakati; Seluruh hasil menjadi milik pihak pengguna jasa; Penyedia bertanggung jawab atas keamanan peralatan dan pelaksanaan di lapangan.', 216000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1225658);
