INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63881094', 63881094, 'analyze_legacy', 'Kab. Sintang', 'kabkota', 'Sekretariat Daerah', 'Belanja Alat/Bahan untuk Kegiatan Kantor- Kertas dan Cover', 'Barang', 'E-Purchasing', 'Kalimantan Barat, Sintang (Kab.)', 3350000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'KERTAS; KERTAS;', 'HVS 70 gr A3 Doble Folio SD; NCR Folio;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1229200);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63881066', 63881066, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Fasilitasi Penyelarasan Kebijakan Nasional pada Pulau Sulawesi, Kepulauan Maluku, dan Pulau Papua', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 238425000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Kawasan Strategis Nasional (KSN) adalah wilayah yang penataan ruangnya diprioritaskan karena mempunyai pengaruh sangat penting secara nasional terhadap kedaulatan negara, pertahanan dan keamanan negara, ekonomi, sosial, budaya, dan/atau lingkungan, termasuk wilayah yang telah ditetapkan sebagai warisan dunia. Penataan ruang KSN dilakukan untuk mengembangkan, melestarikan, melindungi dan/atau mengkoordinasikan keterpaduan pembangunan nilai strategis kawasan dalam mendukung penataan ruang wilayah. Dalam Pasal 14 Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang, dinyatakan bahwa Rencana Tata Ruang (RTR) Pulau/Kepulauan dan KSN merupakan rencana rinci yang disusun sebagai perangkat operasional dari rencana umum tata ruang pada sistem nasional. Selanjutnya PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang RTRWN menetapkan 76 (tujuh puluh enam) KSN. Pada tahun 2015 telah terbit Peraturan Presiden Nomor 32 tahun 2015 tentang Rencana Tata Ruang Kawasan Perbatasan Negara di Provinsi Papua. Dalam rangka diseminasi dan penyamaan persepsi mengenai RTR KSN dan KPN serta sinkronisasi kebijakan nasional (fasilitasi dan koordinasi penyiapan rekomendasi solusi isu pemanfaatan ruang yang ada dalam KSN) kepada stakeholder terkait baik di lingkup Pemerintah Pusat maupun pemerintah daerah, maka pada tahun anggaran 2026 Direktorat Perencanaan Tata Ruang, Direktorat Jenderal Tata Ruang, Kementerian Agraria dan Tata Ruang akan melaksanakan Sinkronisasi Kebijakan Nasional pada Pulau Sulawesi, Kepulauan Maluku, dan Pulau Papua.', 'Kegiatan ini menghasilkan dokumen laporan yang terdiri atas: Laporan Pendahuluan Laporan ini sekurang-kurangnya berisi metoda pelaksanaan masing-masing aktivitas yang tercakup dalam ruang lingkup kegiatan, jadwal pelaksanaan kegiatan secara lebih terinci, Surat Keputusan tentang Pembentukan Tim Swakelola, dan agenda pelaksanaan pekerjaan. Laporan pendahuluan diserahkan selambat-lambatnya 30 (tiga puluh) hari terhitung sejak tanggal dimulainya pekerjaan dalam SK Tim Swakelola. Laporan pendahuluan dicetak pada bulan ke-1 sebanyak 4 (empat) eksemplar. Dokumen Diseminasi RTR Nasional pada Pulau Sulawesi, Kepulauan Maluku, dan Pulau Papua Laporan ini memuat rangkuman dan hasil-hasil kegiatan selama Tahun Anggaran 2026 disertai dengan review dan evaluasi pelaksanaannya (dalam ruang lingkup yang sesuai dengan tugas-tugas kesekretariatan). Prosiding diserahkan pada akhir masa pekerjaan dan Semua dokumen dituangkan dalam format "PDF". Laporan pendahuluan dicetak pada bulan ke-12 sebanyak 4 (empat) eksemplar. Dokumen Inventarisasi Konflik dan Rekomendasi Solusi di dalam KSN pada Pulau Sulawesi, Kepulauan Maluku, dan Pulau Papua Dokumen ini memuat hasil penjaringan isu dalam pemanfaatan ruang serta hasil rekomendasi solusinya. Dokumen diserahkan pada akhir masa pekerjaan dan Semua dokumen dituangkan dalam format "PDF". Laporan pendahuluan dicetak pada bulan ke-12 sebanyak 4 (empat) eksemplar', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1229201);
