INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966462', 63966462, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Menerima Relaas', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 3500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Menerima Relaas merupakan kegiatan administrasi dalam penanganan perkara pertanahan yang dilakukan melalui penerimaan resmi relaas dari pengadilan atau pejabat yang berwenang, sebagai pemberitahuan atau penyampaian dokumen terkait proses hukum yang sedang atau akan berjalan. Kegiatan ini bertujuan untuk memastikan setiap relaas tercatat secara tertib, ditindaklanjuti tepat waktu, serta menjadi dasar dalam proses penanganan perkara dan penyusunan langkah hukum selanjutnya. Kegiatan ini meliputi: • Penerimaan relaas dari pengadilan/pejabat yang berwenang; • Pencatatan relaas dalam buku agenda atau sistem administrasi; • Penelaahan awal isi relaas; • Penyampaian relaas kepada unit atau pejabat terkait; • Pengarsipan dokumen relaas.', 'a. Ruang Lingkup • Relaas panggilan sidang; • Relaas pemberitahuan putusan; • Relaas pemberitahuan upaya hukum (banding, kasasi, PK); • Relaas lain terkait perkara pertanahan. b. Ketentuan Pelaksanaan • Relaas diterima secara resmi dan dicatat sesuai tata naskah dinas; • Penelaahan dilakukan untuk memastikan kejelasan pihak, objek, dan jadwal; • Tindak lanjut dilakukan sesuai ketentuan dan batas waktu yang ditetapkan; • Seluruh proses terdokumentasi secara tertib dan akuntabel. c. Output/Hasil • Bukti penerimaan relaas; • Catatan administrasi penerimaan relaas; • Arsip relaas dalam bentuk fisik dan/atau digital; • Dasar tindak lanjut penanganan perkara. d. Dasar Hukum • HIR/RBg (Hukum Acara Perdata); • Peraturan Mahkamah Agung terkait tata cara relaas; • Peraturan Menteri ATR/BPN tentang Penanganan Perkara dan Kasus Pertanahan; • SOP penanganan perkara pertanahan.', 3500000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1229446);
