INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966440', 63966440, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Pengkajian Kasus', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 3028000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pengkajian Kasus merupakan tahapan lanjutan dalam penanganan kasus pertanahan yang bertujuan untuk melakukan analisis mendalam terhadap aspek yuridis, fisik, dan administratif suatu kasus, guna memperoleh kesimpulan hukum serta rekomendasi penyelesaian yang tepat dan berkeadilan. Kegiatan ini meliputi: • Penelaahan lanjutan data hasil identifikasi kasus; • Analisis data yuridis (alas hak, riwayat tanah, putusan pengadilan bila ada); • Analisis data fisik (letak, luas, batas, penggunaan tanah); • Analisis kesesuaian dengan peraturan perundang-undangan; • Perumusan kesimpulan dan rekomendasi tindak lanjut penanganan kasus.', 'a. Ruang Lingkup Pengkajian • Sengketa, konflik, dan perkara pertanahan; • Permasalahan administrasi pertanahan; • Permasalahan penguasaan, pemilikan, penggunaan, dan pemanfaatan tanah (P4T). b. Ketentuan Pelaksanaan • Pengkajian dilakukan secara objektif, profesional, dan independen; • Menggunakan data dan dokumen yang sah dan dapat dipertanggungjawabkan; • Analisis mengacu pada peraturan perundang-undangan dan kebijakan pertanahan; • Hasil pengkajian menjadi dasar pengambilan keputusan dan tindakan lanjutan. c. Output/Hasil • Dokumen hasil Pengkajian Kasus; • Kesimpulan status hukum kasus; • Rekomendasi penyelesaian (mediasi, fasilitasi, atau langkah hukum); • Arsip administrasi penanganan kasus. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN tentang Penanganan dan Penyelesaian Kasus Pertanahan; • SOP pengkajian dan penyelesaian kasus pertanahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1229449);
