INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966238', 63966238, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Surat Keputusan', 'Barang', 'E-Purchasing', 'Aceh, Pidie Jaya (Kab.)', 6856000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Pekerjaan Surat Keputusan Penetapan Hak Atas Tanah merupakan rangkaian kegiatan administratif dan teknis pertanahan dalam rangka pemberian, penegasan, atau pengakuan hak atas tanah kepada perorangan (WNI) dan/atau badan hukum sesuai ketentuan peraturan perundang-undangan. Kegiatan ini meliputi: 1. Penelitian berkas permohonan hak atas tanah; 2. Pemeriksaan data yuridis dan data fisik bidang tanah; 3. Klarifikasi status penguasaan dan penggunaan tanah; 4. Penyusunan konsep Surat Keputusan Penetapan Hak Atas Tanah; 5. Penetapan dan penandatanganan SK oleh pejabat yang berwenang; 6. Pengarsipan dan penyampaian SK sebagai dasar pendaftaran hak dan penerbitan sertipikat.', 'a. Persyaratan Subjek dan Objek • Subjek hak: perorangan WNI dan/atau badan hukum Indonesia yang sah; • Objek hak: bidang tanah yang memenuhi persyaratan penguasaan dan penggunaan sesuai tata ruang. b. Jenis Hak yang Diproses • Hak Milik (perorangan WNI); • Hak Guna Bangunan (HGB); • Hak Guna Usaha (HGU); • Hak Pakai; • Hak Pengelolaan (sesuai kewenangan). c. Ketentuan Pelaksanaan • Pemeriksaan data fisik mengacu pada hasil pengukuran dan peta bidang tanah; • Pemeriksaan data yuridis mengacu pada alas hak, riwayat tanah, dan dokumen pendukung; • Proses penetapan hak dilaksanakan sesuai SOP dan ketentuan ATR/BPN yang berlaku; • Kewenangan penetapan mengikuti ketentuan peraturan perundang-undangan. d. Output/Hasil • Surat Keputusan Penetapan Hak Atas Tanah yang sah dan ditandatangani pejabat berwenang; • Dokumen SK menjadi dasar penerbitan Sertipikat Hak Atas Tanah; • Arsip fisik dan/atau digital tersimpan dalam sistem administrasi pertanahan. e. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 tentang Peraturan Dasar Pokok-Pokok Agraria; • PP Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN terkait.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1229540);
