INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966414', 63966414, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Identifikasi Kasus', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 3500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Identifikasi Kasus merupakan kegiatan awal dalam penanganan kasus pertanahan yang bertujuan untuk memperoleh gambaran awal, klasifikasi, dan status suatu kasus secara objektif dan sistematis. Kegiatan ini dilakukan melalui pengumpulan, penelaahan, dan analisis data awal guna menentukan jenis kasus, para pihak yang terlibat, objek sengketa, serta potensi penyelesaian. Kegiatan ini meliputi: 1. Penerimaan dan pencatatan pengaduan/laporan kasus; 2. Pengumpulan data dan dokumen awal; 3. Penelaahan data yuridis dan data fisik; 4. Klarifikasi awal kepada pihak terkait (bila diperlukan); 5. Penyusunan hasil identifikasi dan rekomendasi tindak lanjut.', 'a. Ruang Lingkup Kasus • Sengketa, konflik, dan perkara pertanahan; • Permasalahan administrasi pertanahan; • Permasalahan penguasaan, pemilikan, penggunaan, dan pemanfaatan tanah (P4T). b. Ketentuan Pelaksanaan • Identifikasi dilakukan secara objektif, transparan, dan akuntabel; • Data yang digunakan berasal dari dokumen resmi dan/atau keterangan para pihak; • Analisis mengacu pada peraturan perundang-undangan di bidang pertanahan; • Hasil identifikasi menjadi dasar penentuan penanganan lanjutan. c. Output/Hasil • Dokumen hasil Identifikasi Kasus; • Ringkasan jenis dan status kasus; • Peta atau data pendukung (jika diperlukan); • Arsip administrasi penanganan kasus. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN tentang Penanganan dan Penyelesaian Kasus Pertanahan; • SOP penanganan kasus pertanahan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1229689);
