INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63966577', 63966577, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KABUPATEN PIDIE JAYA', 'Penerbitan Sertipikat ( SHAT PTSL ASN Kategori 3 )', 'Barang', 'Pengadaan Langsung', 'Aceh, Pidie Jaya (Kab.)', 19500000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Penerbitan Sertipikat (SHAT PTSL ASN Kategori 3) merupakan kegiatan pelayanan pertanahan dalam rangka penerbitan sertipikat hak atas tanah berdasarkan SK Hak/Pengesahan Data Fisik dan Yuridis (SHAT) hasil Pendaftaran Tanah Sistematis Lengkap (PTSL) ASN yang termasuk dalam Kategori 3. Kegiatan ini bertujuan memberikan kepastian hukum dan perlindungan hukum kepada pemegang hak atas tanah melalui penerbitan sertipikat yang sah. Kegiatan ini meliputi: • Penelitian akhir kelengkapan berkas SHAT; • Pembukuan hak dalam buku tanah; • Pencetakan sertipikat hak atas tanah; • Penandatanganan sertipikat oleh pejabat berwenang; • Pengadministrasian, pengarsipan, dan penyerahan sertipikat kepada pemegang hak.', 'a. Kriteria Kategori 3 • Bidang tanah telah memperoleh SK Hak/Pengesahan Data Fisik dan Yuridis (SHAT); • Tidak terdapat sengketa, konflik, atau perkara; • Data fisik dan data yuridis telah disahkan. b. Ketentuan Pelaksanaan • Pembukuan hak dilaksanakan sesuai ketentuan pendaftaran tanah; • Sertipikat diterbitkan berdasarkan data yang telah diverifikasi; • Proses penerbitan mengikuti SOP PTSL ASN; • Pelayanan dilaksanakan secara tertib, transparan, dan akuntabel. c. Output/Hasil • Sertipikat Hak Atas Tanah (Hak Milik/Hak lainnya sesuai ketentuan); • Buku Tanah; • Surat Ukur/Peta Bidang Tanah; • Arsip administrasi pertanahan fisik dan/atau digital. d. Dasar Hukum • Undang-Undang Nomor 5 Tahun 1960 (UUPA); • PP Nomor 24 Tahun 1997 tentang Pendaftaran Tanah; • PP Nomor 18 Tahun 2021; • Peraturan Menteri ATR/BPN tentang PTSL; • Petunjuk Teknis PTSL ASN yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1229811);
